  assert.equal(v.thinking, 'FIRST THOUGHT.\n\n— read Chapter One, then —\n\nSECOND THOUGHT.\n\n— read Chapter Two, then —\n\nTHIRD THOUGHT.', v.thinking);
  await reset();
