  await setHouse({}, { checksFrom: 0, you: { name: 'Jovan' } });
  const ask = { direction: 'She lights it.', length: 'scene' };
  const b = await makeBook([[{ text: 'Rias lit the lamp.', model: 'writer-a', how: 'write', ask }]], { brief: '{{char}} is {{user}}\'s older sister.' });
