  assert.deepEqual(bib.bibItems(b.novel(), { [b.ids[0]]: b.ch(0) }).map((it) => [it.name, it.facts.map((f) => f.fact)]), [['Ilse', ['Ilse’s eyes are violet.', 'Ilse cut her hair short.']]]);
