/* (2.12.41, the review of 2.12.40's audit) */
const TOM_41 = 'Tom, Mara’s brother, comes home from the war.';
const tomBook = async () => {
  const b = await makeBook([['The alley was quiet.', { text: 'Tom came home from the war. Mara held him at the door.', ask: { direction: TOM_41, length: 'scene' } }]], { manual: true });
  markAllSeen(b);
  store.change('novel', b.novelId, (n) => {
    n.notes.people.push({ id: 'pe-t', name: 'Tom', aka: [], about: 'Mara’s brother, home from the war.', updated: { chapterId: b.ids[0], at: 1 } });
    n.notes.people.push({ id: 'pe-m', name: 'Mara', aka: [], about: 'She waits at the door.', updated: { chapterId: b.ids[0], at: 1 } });
  }, { now: true });
  return b;
};
await test('what his hand took out of a page is decided as the change is made: his premise stays out of the book once his edit took its name out, though a reading then takes that name’s card away; a slip he mended and a name changed everywhere leave it the book, and a name changed everywhere is never told as his partner’s words', async () => {
  await setHouse();
  const standing = (b) => archivist.standingPremises(b.novel(), { [b.ids[0]]: b.ch() }).length;
  const b = await tomBook();
  assert.equal(writer.saveEdit({ novelId: b.novelId, chapterId: b.ids[0], passageId: b.ch().passages[1].id, text: 'Mara waited alone at the door. She had never had a brother.' }), true);
  assert.deepEqual(picked(b.ch().passages[1]).before.at(-1).took, ['tom'], 'what his edit took out, kept with it');
  assert.equal(standing(b), 0, 'his edit took Tom out: the premise is not the book');
  /* the reading takes Tom's card away: the premise stays out of the book */
  await reset();
  await script([{ text: JSON.stringify({ gone: [{ kind: 'people', name: 'Tom' }] }) }]);
  await archivist.run(b.novelId);
  assert.equal(b.novel().notes.people.some((c) => c.id === 'pe-t'), false, 'Tom goes');
  assert.equal(standing(b), 0, 'still not the book, with no card of Tom’s left');
  assert.equal(archivist.groundsOf(b.novel()).loose.includes(' tom '), false, 'never a ground again');
  /* the check, told by the premise to add Tom back: nothing of the book gives him */
  await reset();
  archivist.askAudit(b.novelId);
  await script([{ text: JSON.stringify({ clear: false, verdict: 'Checked.', people: [{ name: 'Tom', about: 'Mara’s brother, home from the war.', why: 'his premise' }] }) }]);
  await archivist.run(b.novelId);
  assert.equal(b.novel().notes.people.some((c) => c.name === 'Tom'), false, 'Tom is not made again');
  await putAway(b);
  /* a slip he mended, then a name changed everywhere: the premise is the book, and nothing of his partner's is told */
  const t = await tomBook();
  assert.equal(writer.saveEdit({ novelId: t.novelId, chapterId: t.ids[0], passageId: t.ch().passages[1].id, text: 'Tom came home from the war. Mara held him at the door!' }), true);
  assert.equal(changes.makeChange(t.novelId, { rename: { from: 'Mara', to: 'Marla' } }).status, 'made');
  const v = picked(t.ch().passages[1]);
  assert.deepEqual([v.text, v.before.at(-1).rename, v.hands], ['Tom came home from the war. Marla held him at the door!', true, ['you']], 'the name changed everywhere marked so — no one’s hand');
  assert.deepEqual(shape.laterWords(t.ch().passages[1]).map((w) => w.how), ['edit'], 'never told as his partner’s words');
  assert.equal(standing(t), 1, 'the premise is still the book');
  await putAway(t);
});

await test('what a change took out of a page is kept past the five changes kept on it; one kept before 2.12.41 is read from his own words and the words now — his partner’s then never counted', () => {
  const page = () => shape.newPassage('ai', 'Tom came home from the war. Mara held him at the door.', { how: 'write', ask: { direction: TOM_41, length: 'scene' } });
  const standing = (p) => { const { novel, chapter } = shape.newNovel({ title: 'Kept' }); chapter.passages.push(p); return archivist.standingPremises(novel, { [chapter.id]: chapter }).length; };
  const step = (p, text, by, extra = {}) => { const v = picked(p); Object.assign(v, shape.inPlaceFields(v, text, by, { at: Date.now(), extra })); };
  /* a fix by itself, his edit taking Tom out, then four more fixes: his change goes from the list, what it took out stays */
  const p = page();
  step(p, 'Tom came home from the war. Mara held him at the door!', 'checker', { auto: true });
  step(p, 'Mara waited alone at the door. She had never had a brother.', 'you');
  for (let i = 0; i < 4; i++) step(p, `${picked(p).text} (${i})`, 'checker', { auto: true });
  const v = picked(p);
  assert.equal(v.before.some((x) => x.by === 'you'), false, 'his change let go from the list');
  assert.deepEqual(v.gone && v.gone.you && v.gone.you.took, ['tom'], 'what it took out, kept on the version');
  assert.deepEqual(shape.laterWords(p).map((w) => w.how), ['edit'], 'his change still told');
  assert.equal(standing(p), 0, 'the premise is still not the book');
  /* kept before 2.12.41, with no record of what it took out */
  const old = (by) => { const q = page(); step(q, 'Mara waited alone at the door.', by); const w = picked(q); delete w.before.at(-1).took; delete w.before.at(-1).moved; return q; };
  assert.equal(standing(old('you')), 0, 'his: read from his words and the words now');
  assert.equal(standing(old('partner')), 1, 'his partner’s then: a name changed everywhere could not be told from it, so never counted');
});

await test('his card is never overturned by a premise of his that a newer edit of his on its passage already stands over — only by one whose passage has no later word of his', async () => {
  await setHouse();
  const t0 = Date.now() - 600000;
  const PREM = 'Jovan Wessex is a fledgling vampire, turned last winter.';
  const make = async () => {
    const b = await makeBook([['The alley was quiet.', { text: 'Jovan Wessex, a fledgling vampire, hit the wall.', ask: { direction: PREM, length: 'scene' } }]], { manual: true });
    markAllSeen(b);
    store.change('novel', b.novelId, (n) => { n.notes.people.push({ id: 'pe-j', name: 'Jovan Wessex', aka: [], about: 'Jovan Wessex is a higher vampire — the Sanguelis raised him.', updated: { by: 'you', hisAt: t0, at: t0 } }); }, { now: true });
    return b;
  };
  const check = async (b) => {
    await reset();
    archivist.askAudit(b.novelId);
    await script([{ text: JSON.stringify({ clear: false, verdict: 'Checked.', mine: [{ kind: 'people', name: 'Jovan Wessex', holds: false, contradicts: 'Jovan Wessex is a fledgling vampire', about: 'Jovan Wessex is a fledgling vampire, turned last winter.', why: 'the premise says fledgling' }] }) }]);
    await archivist.run(b.novelId);
    return b.novel().notes.people.find((c) => c.id === 'pe-j');
  };
  /* his card first, the premise after it, then his own edit writing his card's word back into the page */
  const b = await make();
  assert.equal(writer.saveEdit({ novelId: b.novelId, chapterId: b.ids[0], passageId: b.ch().passages[1].id, text: 'Jovan Wessex, a higher vampire, hit the wall.' }), true);
  await reset();
  await script([{ text: JSON.stringify({ people: [] }) }]);
  await archivist.run(b.novelId);
  assert.equal(archivist.standingPremises(b.novel(), { [b.ids[0]]: b.ch() }).length, 1, 'the premise still the book (no name taken out)');
  const card = await check(b);
  assert.deepEqual([card.about, shape.hisField(card, 'about')], ['Jovan Wessex is a higher vampire — the Sanguelis raised him.', true], 'his card stands');
  await putAway(b);
  /* the same, its passage untouched since: the premise typed after his card is his newer word */
  const c = await make();
  const card2 = await check(c);
  assert.equal(card2.about, 'Jovan Wessex is a fledgling vampire, turned last winter.', 'put right from it');
  await putAway(c);
});

await test('his premise and his notes since share one room beside the page — the oldest cut first, his newest note kept, what is left out said — so a small helper’s reading never outgrows its room', async () => {
  await setHouse({ context: 8000 });
  const sentence = 'Jovan crossed the hall of the elders, counting the lamps, and the council watched him without a word while the rain beat on the high windows. ';
  const PREM = 'The Sanguelis rule the city from the old cathedral, and a hunter turned by an elder keeps his oath to the house that turned him. '.repeat(12).trim();
  const NOTE = (i) => `Note ${i}: ${'Keep the council silent and the rain loud; let him count the lamps slower, and let the elders never look away from him while he walks the length of the hall. '.repeat(16)}`.trim();
  const b = await makeBook([['The alley was quiet.']], { manual: true });
  markAllSeen(b);
  const p = shape.newPassage('ai', sentence.repeat(30), { how: 'write', ask: { direction: PREM, length: 'scene' } });
  let from = p.versions[0];
  for (let i = 1; i <= 4; i++) {
    const v = shape.newVersion({ how: 'rewrite', text: `${sentence.repeat(30)}(take ${i})`, ask: { note: NOTE(i), premise: PREM }, from: from.id, at: Date.now() + i });
    p.versions.push(v);
    from = v;
  }
  p.pick = p.versions.length - 1;
  store.change('chapter', b.ids[0], shape.chapterSteps.addPassage(p), { now: true });
  await reset();
  await script(Array.from({ length: 12 }, () => ({ text: JSON.stringify({ people: [] }) })));
  await archivist.run(b.novelId);
  const reads = (await requests()).filter((x) => String(x.body.messages.at(-1).content).includes('Update the notes'));
  const sizes = reads.map((x) => util.estimateTokens(x.body.messages.map((m) => String(m.content)).join('\n')));
  assert.ok(reads.length >= 1 && Math.max(...sizes) <= 4800, `every reading within its room (${sizes.join(', ')})`);
  const first = String(reads[0].body.messages.at(-1).content);
  assert.ok(first.includes('Since then I had it written again with the note “Note 4:'), 'his newest note beside it');
  assert.ok(first.includes('(Three earlier changes of mine to it are left out here to save room.)') && !first.includes('Note 1:'), 'the oldest cut first, and said');
  assert.ok(first.includes('(the rest of it is left out here to save room)\n"""'), 'the premise by its opening');
  assert.deepEqual(archivist.changesIn(b.novel(), b.ch()).changes, [], 'the page read');
  await putAway(b);
  await setHouse();
});

await test('his premise and his entry are weighed by which he wrote after the other: the reading and the check are told beside each that the newer one stands where they differ', async () => {
  await setHouse();
  const PREM = 'Jovan Wessex is now an elder of the Sanguelis, raised by the council.';
  const b = await makeBook([['The alley was quiet.']], { manual: true });
  markAllSeen(b);
  store.change('chapter', b.ids[0], shape.chapterSteps.addPassage(shape.newPassage('ai', 'Jovan Wessex rose in the cathedral.', { how: 'write', ask: { direction: PREM, length: 'scene' } })), { now: true });
  store.change('novel', b.novelId, (n) => {
    n.notes.people.push({ id: 'pe-j', name: 'Jovan Wessex', aka: [], about: 'A hunter.', updated: { chapterId: b.ids[0], at: 1 } });
    n.notes.lore.push({ id: 'lo-s', name: 'Sanguelis', aka: [], about: 'A council.', updated: { chapterId: b.ids[0], at: 1 } });
    n.bibliography = [
      bib.tidyEntry(bib.newEntry({ id: 'bb-j', name: 'Jovan Wessex', kind: 'people', text: 'A novice hunter of the Order. Human, and he stays human.', at: Date.now() + 60000 })),
      bib.tidyEntry(bib.newEntry({ id: 'bb-s', name: 'Sanguelis', kind: 'groups', text: 'The council of the elder houses. It raises no one.', at: 1 })),
    ];
  }, { now: true });
  await reset();
  await script([{ text: JSON.stringify({ people: [] }) }]);
  await archivist.run(b.novelId);
  const sent = (await requests()).map((x) => String(x.body.messages.at(-1).content)).find((m) => m.includes('Update the notes')) || '';
  assert.ok(sent.includes('My bibliography’s entry for Jovan Wessex was written after this premise: where they differ, the entry stands.'), sent.slice(sent.indexOf('My premise for it'), sent.indexOf('My premise for it') + 400));
  assert.ok(sent.includes('(Where they differ, my premise typed after an entry stands over it — Sanguelis: my premise for Chapter One, Passage 2.)'), 'after his entries: the premise typed after the Sanguelis entry');
  assert.ok(sent.includes('the newer one stands where the two differ'), 'told what that means');
  await reset();
  archivist.askAudit(b.novelId);
  await script([{ text: JSON.stringify({ clear: true, verdict: 'Checked.' }) }]);
  await archivist.run(b.novelId);
  const check = (await requests()).map((x) => String(x.body.messages.at(-1).content)).find((m) => m.includes(prompts.AUDIT_ASK)) || '';
  assert.ok(check.includes(`[Chapter One, Passage 2] ${PREM} — my bibliography’s entry for Jovan Wessex, written after it, stands over it where they differ`), check.slice(check.indexOf('My premises'), check.indexOf('My premises') + 700));
  assert.ok(check.includes('Sanguelis: my premise for Chapter One, Passage 2') && check.includes('the newer one stands where the two differ'), 'the check told the same');
  await putAway(b);
});

/* (2.12.41, the review of 2.12.41) */
await test('what his edit took out of a page is never forgotten: a Go on that leaves his change behind keeps it, and an edit kept before 2.12.41 is read against the words right after it — never blamed for a fix or a name changed after it', async () => {
  await setHouse();
  const standing = (b) => archivist.standingPremises(b.novel(), { [b.ids[0]]: b.ch() }).length;
  /* a page cut short: his edit takes Tom out, a name changed everywhere then touches its last words, then Go on */
  const b = await makeBook([['The alley was quiet.', { text: 'Tom came home from the war, thin and quiet. Mara held him at the door', cut: true, cutWhy: 'it reached the reply length', ask: { direction: TOM_41, length: 'scene' } }]], { manual: true });
  markAllSeen(b);
  const pid = b.ch().passages[1].id;
  assert.equal(writer.saveEdit({ novelId: b.novelId, chapterId: b.ids[0], passageId: pid, text: 'Mara came out alone to the gate, thin and quiet. Mara held him at the door' }), true);
  assert.equal(changes.makeChange(b.novelId, { rename: { from: 'Mara', to: 'Marla' } }).status, 'made');
  await reset();
  await script([{ text: ', and the rain went on all night.' }]);
  const on = await writer.goOn({ novelId: b.novelId, chapterId: b.ids[0], passageId: pid });
  assert.equal(on.ok, true, JSON.stringify(on));
  const v = picked(b.ch().passages[1]);
  assert.ok(v.text.endsWith('Marla held him at the door, and the rain went on all night.'), v.text);
  assert.equal((v.before || []).length, 0, 'the changes before it left behind by the Go on');
  assert.deepEqual(v.gone && v.gone.you && v.gone.you.took, ['tom'], 'what his edit took out, kept on the version');
  assert.deepEqual(shape.laterWords(b.ch().passages[1]).map((w) => [w.how, w.took]), [['edit', ['tom']]], 'his edit still told');
  assert.equal(standing(b), 0, 'his premise is still not the book');
  await putAway(b);
  /* his edit as 2.12.40 kept it (a comma mended, nothing recorded), then the checker writes "He" for Tom */
  const c = await tomBook();
  const cpid = c.ch().passages[1].id;
  assert.equal(writer.saveEdit({ novelId: c.novelId, chapterId: c.ids[0], passageId: cpid, text: 'Tom came home from the war, and Mara held him at the door.' }), true);
  store.change('chapter', c.ids[0], (ch) => { const x = picked(ch.passages.find((p) => p.id === cpid)).before.at(-1); delete x.took; delete x.moved; delete x.whose; }, { now: true });
  assert.ok(inplace.changeInPlace({ novelId: c.novelId, chapterId: c.ids[0], passageId: cpid, next: 'He came home from the war, and Mara held him at the door.', by: 'checker' }));
  assert.deepEqual(shape.laterWords(c.ch().passages[1]).map((w) => [w.how, w.took]), [['edit', []]], 'his old edit took nothing out — the fix after it did');
  assert.equal(standing(c), 1, 'the premise is still the book');
  await putAway(c);
});

await test('a name his edit takes out of a page is told by the book’s names as they are then — a name the page also writes as a word (Will, Rose), a premise typed in small letters — and a name only joined or parted at its hyphen is never taken out', async () => {
  await setHouse();
  const run = async (premise, page, edit, cards = []) => {
    const b = await makeBook([['The alley was quiet.', { text: page, ask: { direction: premise, length: 'scene' } }]], { manual: true });
    markAllSeen(b);
    store.change('novel', b.novelId, (n) => { for (const [id, name, kind = 'people', about = 'Of the book.'] of cards) n.notes[kind].push({ id, name, aka: [], about, updated: { chapterId: b.ids[0], at: 1 } }); }, { now: true });
    assert.equal(writer.saveEdit({ novelId: b.novelId, chapterId: b.ids[0], passageId: b.ch().passages[1].id, text: edit }), true);
    const out = { took: picked(b.ch().passages[1]).before.at(-1).took, stands: archivist.standingPremises(b.novel(), { [b.ids[0]]: b.ch() }).length === 1 };
    await putAway(b);
    return out;
  };
  assert.deepEqual(await run('Will, Mara’s brother, comes home.', 'Will came home. Mara said he will stay.', 'Mara waited alone. She said nobody will stay.', [['pe-w', 'Will'], ['pe-m', 'Mara']]), { took: ['will'], stands: false }, 'Will, a name of the book’s, though the page says “he will”');
  assert.deepEqual(await run('Rose comes home to Mara.', 'Rose came home with a rose in her hair.', 'Mara came home with a rose in her hair.', [['pe-r', 'Rose Hart']]), { took: ['rose'], stands: false }, 'Rose, a word of a card’s name');
  /* a thing's name that is a word too: a name only where the page writes it so inside a sentence */
  assert.deepEqual(await run('The Order hunts at dusk.', 'The Order met. In order to win, the Order fought on.', 'The council met. In order to win, the council fought on.', [['lo-o', 'The Order', 'lore']]), { took: ['order'], stands: false }, 'the Order, inside a sentence');
  assert.deepEqual(await run('Magic costs blood in this book.', 'Magic flared in the hall. The magic was old.', 'The magic was old, and the hall was dark.', [['lo-m', 'Magic', 'lore']]), { took: [], stands: true }, 'Magic opening a sentence, and magic in small letters: no name taken out');
  assert.deepEqual(await run('tom, mara’s brother, comes home from the war.', 'Tom came home from the war. Mara held him.', 'Mara waited alone. She had never had a brother.'), { took: ['tom'], stands: false }, 'a premise typed in small letters');
  assert.deepEqual(await run('Mary-Jane comes home.', 'Mary-Jane came home. Tom held her.', 'Mary Jane came home. Tom held her.'), { took: [], stands: true }, 'the hyphen taken out');
  assert.deepEqual(await run('Mary Jane comes home.', 'Mary Jane came home. Tom held her.', 'Mary-Jane came home. Tom held her.'), { took: [], stands: true }, 'a hyphen put in');
  /* (2.12.41, the review of 2.12.41) his edit right after the page was written, no card for Will yet: the page's own premise gives him */
  assert.deepEqual(await run('Will, Mara’s brother, waits at the gate.', 'Will stood at the gate. Mara said he will stay.', 'Mara stood at the gate. She said he will stay.'), { took: ['will'], stands: false }, 'Will, given by the page’s premise');
  /* a premise that writes "will" or "rose" as a word gives no Will nor Rose; "Will you stay?" taken out is no Will taken out */
  assert.deepEqual(await run('Mara begs Tom to stay, but he will go.', '“Will you stay?” Mara asked. He said he will go at dawn.', '“Stay,” Mara said. He said he will go at dawn.', [['pe-w', 'Will']]), { took: [], stands: true }, '“Will you stay?”');
  assert.deepEqual((await run('Mara will confront her father tonight.', 'Will watched from the door. Mara will confront her father tonight.', 'Mara will confront her father tonight.', [['pe-w', 'Will'], ['pe-m', 'Mara']])).stands, true, 'a premise with “will” in it');
  assert.deepEqual((await run('Mara walks out to the quay as the sun rose.', 'Rose waited on the quay. Mara walked out as the sun rose.', 'Mara walked out as the sun rose.', [['pe-r', 'Rose'], ['pe-m', 'Mara']])).stands, true, 'a premise with “rose” in it');
  /* (Will and Rose the people taken out — the premise's "will" and "rose" are no names of theirs) */
  assert.deepEqual(await run('Mara will confront her father tonight.', 'Will watched from the door. Mara waited.', 'Mara waited.', [['pe-w', 'Will'], ['pe-m', 'Mara']]), { took: ['will'], stands: true }, 'Will taken out, beside a premise saying “will”');
  assert.deepEqual(await run('Mara walks out to the quay as the sun rose.', 'Rose waited on the quay. Mara walked out at dawn.', 'Mara walked out at dawn.', [['pe-r', 'Rose'], ['pe-m', 'Mara']]), { took: ['rose'], stands: true }, 'Rose taken out, beside a premise saying “rose”');
  /* a word of a thing's name only opening a sentence is no name of it */
  assert.deepEqual(await run('The Order keeps the city quiet.', 'Order was the word of the day. The rain fell.', 'Quiet was the word of the day. The rain fell.', [['lo-o', 'The Order', 'lore']]), { took: [], stands: true }, '“Order” opening a sentence');
  /* his name with a possessive, or a contraction, is his name */
  assert.deepEqual(await run('Tom, Mara’s brother, comes home.', 'Tom’s coat hung by the door. Mara touched it.', 'A coat hung by the door. Mara touched it.'), { took: ['tom'], stands: false }, 'Tom’s coat taken out');
  assert.deepEqual(await run('Mara waits for Tom.', 'Mara stood at the door. Mara waited for Tom.', 'Mara’ll wait for Tom.'), { took: [], stands: true }, 'Mara’ll is Mara');
  /* (round 5, the review of round 4) a person of the book's whose name is also a modal or a word, opening each sentence of
   * the premise that names him, the premise saying the word too: his name there — with no card yet, "he will" beside it
   * leaves it a word */
  assert.deepEqual(await run('Will waits at the gate. He will not leave until Mara comes.', 'Will stood at the gate. Mara said he will stay.', 'Mara stood at the gate alone. Nobody would stay.', [['pe-w', 'Will'], ['pe-m', 'Mara']]), { took: ['will'], stands: false }, 'Will, a card’s, opening the premise beside “he will”');
  assert.deepEqual(await run('Rose climbs the tower as the sun rose.', 'Rose climbed the tower. Mara watched as the sun rose.', 'Mara climbed the tower alone as the sun rose.', [['pe-r', 'Rose'], ['pe-m', 'Mara']]), { took: ['rose'], stands: false }, 'Rose, a card’s, beside “the sun rose”');
  assert.deepEqual(await run('Will waits at the gate. He will not leave until Mara comes.', 'Will stood at the gate. Mara said he will stay.', 'Mara stood at the gate alone. Nobody would stay.'), { took: [], stands: true }, 'no card for Will');
  /* a word with a contraction, opening a sentence, is no name by its capital */
  assert.deepEqual(await run('mara runs out of time.', 'Mara ran to the quay. Time’ll tell, she said.', 'Mara ran to the quay.', [['pe-m', 'Mara']]), { took: [], stands: true }, '“Time’ll tell”');
  assert.deepEqual(await run('the storm might break tonight, and mara waits.', 'Mara waited by the window. Might\'ve been the wind.', 'Mara waited by the window.', [['pe-m', 'Mara']]), { took: [], stands: true }, '“Might’ve been the wind”');
  /* his premise as a phone keyboard leaves it, its first word a capital: the name he typed in small letters is hers */
  assert.deepEqual(await run('Tom, mara’s brother, comes home from the war.', 'Tom came home from the war. Mara held him at the door.', 'Tom came home from the war. Nobody held him.', [['pe-t', 'Tom'], ['pe-m', 'Mara']]), { took: ['mara'], stands: false }, '“Tom, mara’s brother”');
  /* Will the modal, its subject after it, a question or none — and Will called, a comma after his name */
  const WILL_LOST = 'Will, Mara’s brother, is lost at sea.';
  assert.deepEqual(await run(WILL_LOST, 'Will he come home, Mara wondered. She waited by the door.', 'Mara waited by the door.', [['pe-w', 'Will'], ['pe-m', 'Mara']]), { took: [], stands: true }, '“Will he come home”');
  assert.deepEqual(await run(WILL_LOST, '“Will, are you there?” Mara called into the dark.', 'Mara called into the dark.', [['pe-w', 'Will'], ['pe-m', 'Mara']]), { took: ['will'], stands: false }, '“Will, are you there?”');
  /* a thing's name typed small in a premise that writes names with capitals inside its sentences is a word ("in order to") */
  assert.deepEqual(await run('Mara keeps the lamps lit, in order to bring Tom home.', 'The Order met at dusk. Mara kept the lamps lit.', 'Mara kept the lamps lit.', [['lo-o', 'The Order', 'lore'], ['pe-m', 'Mara']]), { took: ['order'], stands: true }, '“in order to”');
  /* a word opening a sentence that the book writes in small letters elsewhere is no name, on the page nor in the premise */
  assert.deepEqual(await run('Silence keeps the hall, and Mara waits.', 'Silence fell over the hall. Mara waited.', 'Mara waited.', [['pe-m', 'Mara', 'people', 'She loves the silence of the harbour.']]), { took: [], stands: true }, '“Silence”, a word of a card’s');
  /* (round 5b) a title's stop opens no sentence, as every split of words into sentences reads it (names.js
   * stopEndsNoSentence): "Dr. Will Turner" has Will inside his sentence — a name of the page, "Dr." none — and "Will
   * Dr. Halloway come?" asks, its own stop at the question mark */
  assert.deepEqual(await run('Will, the healer, waits at the gate.', 'Dr. Will Turner waits at the gate. Mara said he will stay.', 'Mara said he will stay.'), { took: ['turner', 'will'], stands: false }, '“Dr. Will Turner”');
  assert.deepEqual(await run(WILL_LOST, '“Will Dr. Halloway come?” Mara asked. He said he will.', 'Mara asked. He said he will.', [['pe-w', 'Will'], ['pe-m', 'Mara']]), { took: ['halloway'], stands: true }, '“Will Dr. Halloway come?”');
  /* and what the book writes of a word: "Halloway" after "Dr." is written inside a sentence */
  const told = namesjs.bookEvidence(['Dr. Halloway treats the hunters. Mr. Venn waits.']);
  assert.deepEqual([told.mid('halloway'), told.open('halloway'), told.mid('venn'), told.open('venn')], [true, false, true, false]);
});

await test('a page is his own words where most of the words on it now are his own hand’s — his words his partner wrote over are his no longer, his own written over his partner’s are — however many changes went, a Go on and a name changed everywhere', () => {
  const W = (n, tag) => Array.from({ length: n }, (_, i) => `${tag}${i}`).join(' ');
  const page = () => shape.newPassage('ai', W(100, 'writer'), { how: 'write', ask: { direction: '', length: 'scene' } });
  const step = (p, text, by, extra = {}) => { const v = picked(p); Object.assign(v, shape.inPlaceFields(v, text, by, { at: Date.now(), extra })); return p; };
  const old = (p) => { const v = picked(p); delete v.whose; for (const x of v.before || []) delete x.whose; return p; };
  const overHis = () => step(step(page(), W(120, 'his'), 'you'), W(100, 'partner'), 'partner');
  const overPartner = () => step(step(page(), W(100, 'partner'), 'partner'), W(100, 'his'), 'you');
  assert.equal(shape.ownWords(overHis()), false, 'his words, then his partner’s over all of them');
  assert.equal(shape.ownWords(overPartner()), true, 'his partner’s, then his own over all of them');
  assert.deepEqual([shape.ownWords(old(overHis())), shape.ownWords(old(overPartner()))], [false, true], 'the same kept before 2.12.41, worked out from the words before');
  /* a page he wrote himself: his, until his partner's change writes over most of it */
  const mine = () => shape.newPassage('you', W(100, 'mine'));
  assert.equal(shape.ownWords(mine()), true, 'a page he wrote himself');
  assert.equal(shape.ownWords(step(mine(), `${W(40, 'partner')} ${W(100, 'mine').split(' ').slice(40).join(' ')}`, 'partner')), true, 'his partner’s change over forty of his hundred words');
  assert.equal(shape.ownWords(step(mine(), W(100, 'partner'), 'partner')), false, 'his partner’s change over all of his own page');
  const most = step(page(), `${W(51, 'his')} ${W(49, 'writer')}`, 'you');
  assert.equal(shape.ownWords(most), true, 'fifty-one words of a hundred his');
  step(most, picked(most).text.replace('his3 ', 'Marla '), 'partner', { rename: true });
  assert.equal(shape.ownWords(most), true, 'a name changed everywhere in his words keeps them his');
  for (let i = 0; i < 6; i++) step(most, picked(most).text.replace(`writer${i} `, `fix${i} `), 'checker', { auto: true });
  assert.equal(shape.ownWords(most), true, 'his still, past the five changes kept — the checker’s words in the writer’s place');
  const v = picked(most);
  Object.assign(v, inplace.grownFields({ ...v }, ` ${W(200, 'more')}`));
  v.text += ` ${W(200, 'more')}`;
  assert.equal(shape.ownWords(most), false, 'the writer’s Go on made the page the writer’s for the most part');
  /* (2.12.41, the review of 2.12.41) a Go on that joins on in the middle of a word cut short: one hand for each word, and
   * the next change finds them so */
  const lay = (p, f) => { const x = picked(p); for (const [k, val] of Object.entries(f)) { if (val === undefined) delete x[k]; else x[k] = val; } return p; };
  const cut = shape.newPassage('ai', 'The rain came down on the old harbour and the boats knocked together in the dark while Mara waited by the do', { how: 'write' });
  lay(cut, shape.inPlaceFields(picked(cut), 'Mara stood alone under the broken lamp, counting the ships that never came back, her hand on the cold rail of the do', 'you', { keepEnd: true }));
  lay(cut, inplace.grownFields({ ...picked(cut) }, 'or. Nothing moved.'));
  picked(cut).text += 'or. Nothing moved.';
  const counted = (x) => picked(x).whose.runs.reduce((s, [, k]) => s + k, 0);
  assert.equal(counted(cut), 25, 'a hand for each of the 25 words, “door” once');
  /* (kept with a hand too many, as such a Go on kept it before: the one too many of the writer's words it put in taken off) */
  picked(cut).whose = { ...picked(cut).whose, runs: [...picked(cut).whose.runs, ['w', 1]] };
  lay(cut, shape.inPlaceFields(picked(cut), picked(cut).text.replace('cold rail', 'cold iron rail'), 'checker'));
  assert.deepEqual([counted(cut), shape.ownWords(cut)], [26, true], 'his still, after the checker put “iron” in');
  /* a long page of his, the checker's mends scattered over it past 600 changes: each word his where it stands as he wrote it */
  const long = Array.from({ length: 2400 }, (_, i) => `w${i}`);
  const own = shape.newPassage('you', long.join(' '));
  const mended = long.map((w, i) => (i % 7 === 3 && i < 7 * 330 ? `x${i}` : w));
  lay(own, shape.inPlaceFields(picked(own), mended.join(' '), 'checker'));
  assert.equal(picked(own).whose.runs.filter(([h]) => h === 'you').reduce((s, [, k]) => s + k, 0), 2070, 'his 2,070 words of 2,400');
  assert.equal(shape.ownWords(own), true);
  /* a few of his own page's words written again at his note: the rest are still his — by the version's own kind, never
   * the page's it came from; a page brought in from a file is no words of his hand */
  const selected = (imported) => {
    const p = shape.newPassage('you', W(100, 'his'), imported ? { how: 'imported' } : {});
    const base = picked(p);
    p.versions.push(shape.newVersion({ how: 'selection', ask: { note: 'Sharper.', from: 0, to: 20 }, text: `${W(10, 'new')} ${W(100, 'his').split(' ').slice(5).join(' ')}`, base: base.id, ...shape.rootOf(base) }));
    p.pick = 1;
    return p;
  };
  assert.deepEqual([shape.ownWords(selected(false)), shape.hisChange(picked(selected(false)))], [true, true], 'a few of his own page’s words written again');
  assert.deepEqual([shape.ownWords(selected(true)), shape.hisChange(picked(selected(true)))], [false, true], 'on a page brought in from a file');
  /* and on the writer's page most of whose words are his edit's: the rest still his */
  const edited = step(page(), `${W(80, 'his')} ${W(20, 'writer')}`, 'you');
  const eb = picked(edited);
  edited.versions.push(shape.newVersion({ how: 'selection', ask: { note: 'Sharper.', from: 0, to: 10 }, text: `${W(5, 'new')} ${eb.text.split(' ').slice(5).join(' ')}`, base: eb.id, ...shape.rootOf(eb) }));
  edited.pick = 1;
  assert.equal(shape.ownWords(edited), true, 'a few words written again on the writer’s page his edit made his for the most part');
  /* a name changed everywhere marked so after its hands were worked out (when the book opened): worked out again */
  const named = shape.newPassage('you', `${W(40, 'his')} ${Array(60).fill('Mara').join(' ')}`);
  lay(named, shape.inPlaceFields(picked(named), picked(named).text.replace(/Mara/g, 'Marla'), 'partner'));
  delete picked(named).whose;
  assert.equal(shape.ownWords(named), false, 'his partner’s sixty words, as kept before 2.12.41');
  picked(named).before.at(-1).rename = true;
  assert.equal(shape.ownWords(named), true, 'marked a name changed everywhere: the words are his again');
});

await test('a Go on keeps who put in the words of a page made from another — a few of his own page’s words written again stay a page of his — and what an old edit of his it leaves behind took out, by the page’s own premise; an old edit reads the same while it is kept and once it is let go', async () => {
  await setHouse();
  const standing = (b) => archivist.standingPremises(b.novel(), { [b.ids[0]]: b.ch() }).map((x) => x.text);
  const MINE = 'Mara called from the quay. Mara waited by the lamp. Mara counted the ships as they came in, one by one, until the light went. Mara wept for the ones that did not come home.';
  const WILL = 'Will, Mara’s brother, waits at the gate.';
  const b = await makeBook([[{ text: MINE, how: 'mine' }, { text: 'Will stood at the gate. Mara said he will stay by the door.', model: 'writer-a', ask: { direction: WILL, length: 'scene' } }]], { manual: true });
  markAllSeen(b);
  /* his own page, its last words written again at his note and cut short — Go on may carry it on */
  const p0 = b.ch().passages[0];
  const base = picked(p0);
  store.change('chapter', b.ids[0], shape.chapterSteps.addVersion(p0.id, shape.newVersion({ how: 'selection', ask: { note: 'Gentler.', from: MINE.indexOf('Mara wept'), to: MINE.length }, text: MINE.replace('Mara wept for the ones that did not come home.', 'She grieved quietly for the lost'), base: base.id, ...shape.rootOf(base), cut: true, endCut: true })), { now: true });
  assert.equal(shape.ownWords(b.ch().passages[0]), true, 'a few of his words written again: his page still');
  /* an edit of his on the writer's page, kept before 2.12.41 (nothing kept of what it did), that took Will out — the page's
   * premise gives Will, no card does */
  store.change('chapter', b.ids[0], (ch) => {
    const v = picked(ch.passages[1]);
    v.written = v.text;
    v.before = [{ text: v.text, by: 'you', at: 100 }];
    v.hands = ['you'];
    v.text = 'Mara stood at the gate. She said he would stay.';
  }, { now: true });
  assert.deepEqual([shape.laterWords(b.ch().passages[1]).map((w) => w.took), standing(b)], [[['will']], []], 'his old edit took Will out: the premise is no longer the book');
  await script([{ text: 'ones, and the sea kept them.' }, { text: 'Night fell over the harbour.' }]);
  assert.equal((await writer.goOn({ novelId: b.novelId, chapterId: b.ids[0], passageId: p0.id })).ok, true);
  const v0 = picked(b.ch().passages[0]);
  assert.ok(v0.text.endsWith('the sea kept them.'), v0.text);
  assert.deepEqual([shape.ownWords(b.ch().passages[0]), v0.whose.runs.some(([h]) => h === 'you')], [true, true], `his words kept his through the Go on: ${JSON.stringify(v0.whose.runs)}`);
  assert.equal((await writer.goOn({ novelId: b.novelId, chapterId: b.ids[0], passageId: b.ch().passages[1].id })).ok, true);
  const v1 = picked(b.ch().passages[1]);
  assert.deepEqual([v1.before, v1.gone && v1.gone.you && v1.gone.you.took, standing(b)], [undefined, ['will'], []], 'left behind by the Go on, what it took out kept: the premise still not the book');
  await putAway(b);
  /* an old edit of his, kept before 2.12.41, let go past the changes kept: what it took out read as it read while kept,
   * never with the book's names of now (his premise saying “he will” too: Will no name of it then — a card for Will made
   * since) */
  const names = namesjs.nameWordsOf(['Will', 'Mara'], []);
  const p = shape.newPassage('ai', 'Will stood at the gate. Mara said he will stay.', { how: 'write', ask: { direction: 'Will waits at the gate. He will not leave until Mara comes.', length: 'scene' } });
  const v = picked(p);
  v.written = v.text;
  v.before = [{ text: v.text, by: 'checker', at: 50 }, { text: 'Will stood at the old gate. Mara said he will stay.', by: 'you', at: 100 }];
  v.hands = ['checker', 'you'];
  v.text = 'Mara stood at the old gate. She said he will stay.';
  const tookWhileKept = shape.laterWords(p).map((w) => w.took);
  for (const w of ['waited', 'stood', 'waited', 'stood']) Object.assign(v, shape.inPlaceFields(v, v.text.replace(/stood|waited/, w), 'checker', { names, passage: p }));
  assert.deepEqual([v.before.length, v.before.some((x) => x.by === 'you'), v.gone && v.gone.you && v.gone.you.took, shape.laterWords(p).map((w) => w.took)], [shape.BEFORE_KEEP, false, tookWhileKept[0], tookWhileKept], `the same while kept and once let go: ${JSON.stringify(tookWhileKept)}`);
});

await test('a few of his own page’s words written again, then the version they came from removed (⋯ → Remove this version): the rest are still his words, and the page his own (round 5)', async () => {
  await setHouse();
  const W = (n, w) => Array.from({ length: n }, (_, i) => `${w}${i}`).join(' ');
  const b = await makeBook([[{ text: W(100, 'his'), how: 'mine' }]], { manual: true });
  markAllSeen(b);
  const p0 = b.ch().passages[0];
  const base = picked(p0);
  store.change('chapter', b.ids[0], shape.chapterSteps.addVersion(p0.id, shape.newVersion({ how: 'selection', ask: { note: 'Sharper.', from: 0, to: 20 }, text: `${W(10, 'new')} ${W(100, 'his').split(' ').slice(5).join(' ')}`, base: base.id, ...shape.rootOf(base) })), { now: true });
  const hisWords = (v) => (v.whose ? v.whose.runs : shape.whoseNow(v, b.ch().passages[0]).runs).filter(([h]) => h === 'you').reduce((s, [, k]) => s + k, 0);
  assert.deepEqual([shape.ownWords(b.ch().passages[0]), hisWords(picked(b.ch().passages[0]))], [true, 95]);
  /* (what the menu's Remove this version lays: desk.js removeVersions) */
  store.change('chapter', b.ids[0], shape.chapterSteps.removeVersion(p0.id, base.id), { now: true });
  const p = b.ch().passages[0];
  assert.deepEqual([p.versions.map((v) => v.how), shape.ownWords(p), hisWords(picked(p)), shape.whoseFits(picked(p))], [['selection'], true, 95, true], JSON.stringify(picked(p).whose));
  await putAway(b);
});

await test('a hand on a page that no change kept accounts for is told as a change of that hand only where one can have been let go unsaid — fewer than five kept from before 2.12.41, the first words no longer first — and never where every change kept was made since (round 5)', () => {
  const W = (n, tag) => Array.from({ length: n }, (_, i) => `${tag}${i}`).join(' ');
  const p = shape.newPassage('ai', W(20, 'w'), { how: 'write', ask: { direction: 'Mara keeps the lamp.', length: 'scene' } });
  const v = picked(p);
  /* kept before 2.12.41: his edit and the changes after it left behind by a Go on, one fix kept since — his hand on the
   * page, no change of his kept */
  v.written = W(20, 'w');
  v.before = [{ text: W(20, 'x'), by: 'checker', at: 100, auto: true }];
  v.text = W(20, 'y');
  v.hands = ['you', 'checker'];
  v.done = 500;
  assert.deepEqual(shape.laterWords(p).map((w) => [w.how, w.took, w.at]), [['edit', [], 500]], 'his change let go unsaid');
  /* five kept, every one made since 2.12.41 (each with what it took out): none let go unsaid */
  v.before = Array.from({ length: shape.BEFORE_KEEP }, (_, i) => ({ text: W(20, `f${i}`), by: 'checker', at: 100 + i, took: [] }));
  assert.deepEqual(shape.laterWords(p), [], 'five made since');
  /* kept from before, fewer than five and the first words still first: none */
  v.before = [{ text: W(20, 'w'), by: 'checker', at: 100 }];
  assert.deepEqual(shape.laterWords(p), [], 'the first words still first');
});

await test('his premise and his newest word on its passage never go over their room beside the page: the newest note cut to fit before it goes, and where only one of them can ride, his note — the premise said left out — even beside a page that replaced long words on a small helper', async () => {
  const PREM = 'The Sanguelis rule the city from the old cathedral, and a hunter turned by an elder keeps his oath to the house that turned him. '.repeat(6).trim();
  const note = (i) => `Note ${i}: ${'Keep the council silent and the rain loud; let him count the lamps slower. '.repeat(6)}`.trim();
  const c = (room) => ({ premise: PREM, later: [1, 2, 3].map((i) => ({ how: 'rewrite', note: note(i), at: i })), besideRoom: room, text: 'x' });
  for (const room of [400, 200, 120, 100, prompts.BESIDE_FLOOR, 40, 10, 0]) assert.ok(util.countWords(prompts.premiseBeside(c(room))) <= room, `room ${room}: ${util.countWords(prompts.premiseBeside(c(room)))} words`);
  const at120 = prompts.premiseBeside(c(120));
  assert.ok(at120.includes('“Note 3:') && at120.includes('My premise for it, as I typed it:') && !at120.includes('(What I did to it since is left out'), at120);
  assert.ok(util.countWords(at120) > 110, `the room used: ${util.countWords(at120)} of 120 words`);
  const floor = prompts.premiseBeside(c(prompts.BESIDE_FLOOR));
  assert.ok(floor.startsWith('(My premise for it is left out here to save room.)') && floor.includes('“Note 3:') && floor.includes('(Two earlier changes of mine to it are left out here to save room.)'), floor);
  assert.equal(prompts.premiseBeside(c(40)), '(My premise for it, and what I did to it since, are left out here to save room.)\n');
  assert.equal(prompts.premiseBeside(c(0)), '');
  /* a small helper reads a page written again over long words: what its batch leaves beside them is all but nothing,
   * and his newest note still rides (the reading's room beside the page is never under BESIDE_FLOOR) */
  await setHouse({ context: 8000 });
  const b = await makeBook([['The alley was quiet.']], { manual: true });
  const sentence = 'Jovan crossed the hall of the elders, counting the lamps, and the council watched him without a word while the rain beat on the high windows. ';
  const p = shape.newPassage('ai', sentence.repeat(24).trim(), { how: 'write', ask: { direction: PREM, length: 'scene' } });
  store.change('chapter', b.ids[0], shape.chapterSteps.addPassage(p), { now: true });
  markAllSeen(b);
  store.change('chapter', b.ids[0], (ch) => { const q = ch.passages[1]; q.versions.push(shape.newVersion({ how: 'rewrite', text: sentence.repeat(4).trim(), ask: { note: note(9), premise: PREM }, from: q.versions[0].id, at: Date.now() })); q.pick = 1; }, { now: true });
  await reset();
  await script(Array.from({ length: 6 }, () => ({ text: JSON.stringify({ people: [] }) })));
  await archivist.run(b.novelId);
  const reads = (await requests()).map((x) => String(x.body.messages.at(-1).content)).filter((m) => m.includes('Update the notes'));
  assert.ok(reads.some((m) => m.includes('It used to read:') && m.includes('Since then I had it written again with the note “Note 9:')), reads.map((m) => m.slice(0, 300)).join('\n---\n'));
  await putAway(b);
  await setHouse();
});

await test('his entry is weighed against his premise by when each of its words was written: a sentence added later is the only newer word, his line changed the only newer line, when it rides changes no time, a premise whose time is not known is weighed against nothing — and the check’s correction is undone as it was made', async () => {
  await setHouse();
  const PREM = 'Emilia Vermaine has dyed her hair black since the Burning.';
  const b = await makeBook([[{ text: 'Emilia Vermaine had black hair, cut short.', how: 'mine' }]], { manual: true });
  markAllSeen(b);
  store.change('novel', b.novelId, (n) => { n.notes.people.push({ id: 'pe-e', name: 'Emilia Vermaine', aka: [], about: 'An elder vampire.', updated: { chapterId: b.ids[0], at: 1 } }); }, { now: true });
  const t0 = Date.now() - 20 * 60000;
  store.change('novel', b.novelId, shape.novelSteps.putEntry(bib.tidyEntry(bib.newEntry({ id: 'bb-e', name: 'Emilia Vermaine', kind: 'people', line: 'An elder vampire.', text: 'Emilia Vermaine has silver hair. She rules the youngest house.', at: t0, by: 'you' }))), { now: true });
  const p = shape.newPassage('ai', 'Emilia Vermaine walked the wall at dusk.', { how: 'write', ask: { direction: PREM, length: 'scene' } });
  picked(p).at = Date.now() - 10 * 60000;
  store.change('chapter', b.ids[0], shape.chapterSteps.addPassage(p), { now: true });
  const weigh = () => { const n = b.novel(); const ch = { [b.ids[0]]: b.ch() }; const prem = archivist.premisesWeighed(n, shape.premisesOf(n, ch))[0]; const e = archivist.entriesWeighed(n, ch, bib.entriesOf(n))[0]; return [e.premiseOver, e.premisePart, prem.entryOver, prem.entryPart]; };
  const LABEL = 'Chapter One, Passage 2';
  assert.deepEqual(weigh(), [[LABEL], undefined, undefined, undefined], 'the premise newer than all of the entry');
  /* his partner only sets it to ride always */
  assert.equal(changes.makeChange(b.novelId, { entry: 'Emilia Vermaine', rides: 'always' }).status, 'made');
  assert.deepEqual(weigh(), [[LABEL], undefined, undefined, undefined], 'when it rides changes no time');
  /* Quick add's way, his entry written whole by his partner for him: one sentence added */
  const RAVEN = 'She keeps a raven named Tock.';
  const added = changes.makeChange(b.novelId, { entry: 'Emilia Vermaine', text: `Emilia Vermaine has silver hair. She rules the youngest house. ${RAVEN}` }, { entryBy: 'you' });
  assert.equal(added.status, 'made');
  assert.deepEqual(weigh(), [undefined, [{ label: LABEL, words: [RAVEN] }], undefined, [{ name: 'Emilia Vermaine', words: [RAVEN] }]], 'only the sentence added is newer than the premise');
  /* told so in the reading, in his voice */
  await reset();
  await script([{ text: JSON.stringify({ people: [] }) }]);
  await archivist.run(b.novelId);
  const sent = (await requests()).map((x) => String(x.body.messages.at(-1).content)).find((m) => m.includes('Update the notes')) || '';
  assert.ok(sent.includes(`Of my bibliography’s entry for Emilia Vermaine, I wrote “${RAVEN}” after this premise: where they differ, those words stand; the rest of that entry is older, and the premise stands over it.`), sent.slice(sent.indexOf('My premise for it'), sent.indexOf('My premise for it') + 500));
  assert.ok(sent.includes(`Emilia Vermaine: my premise for ${LABEL}, over all of it but “${RAVEN}”, which I wrote after that premise`), 'and after his entries');
  /* its Undo finds it as the change left it — and the change made again */
  const kept = bib.entriesOf(b.novel())[0];
  assert.equal(changes.undoChange(b.novelId, added).ok, true);
  assert.equal(bib.entriesOf(b.novel())[0].text, 'Emilia Vermaine has silver hair. She rules the youngest house.');
  store.change('novel', b.novelId, shape.novelSteps.putEntry(kept), { now: true });
  assert.deepEqual(bib.entriesOf(b.novel())[0], kept, 'an entry given as its write kept it is kept as given');
  /* the sheet's save (as ui/bibliography.js keeps it): his line changed, and "Emilia" for "She" — no new word of his */
  const live = bib.entriesOf(b.novel())[0];
  store.change('novel', b.novelId, shape.novelSteps.putEntry({ ...bib.tidyEntry({ ...live, line: 'The youngest elder.', text: live.text.replace('She rules', 'Emilia rules') }), at: Date.now(), by: 'you' }), { now: true });
  assert.deepEqual(weigh()[3], [{ name: 'Emilia Vermaine', words: ['The youngest elder.', RAVEN] }], 'his new line and the sentence added: the only newer words');
  /* the check puts his entry right from his own page — and its Undo finds it as the check left it */
  const before = bib.entriesOf(b.novel())[0];
  await reset();
  archivist.askAudit(b.novelId);
  await script([{ text: JSON.stringify({ clear: true, verdict: 'Checked.', mine: [{ kind: 'entry', name: 'Emilia Vermaine', holds: false, contradicts: 'Emilia Vermaine had black hair', text: `Emilia Vermaine has black hair. She rules the youngest house. ${RAVEN}`, why: 'his own page' }] }) }]);
  await archivist.run(b.novelId);
  assert.equal(bib.entriesOf(b.novel())[0].text, `Emilia Vermaine has black hair. She rules the youngest house. ${RAVEN}`, 'put right');
  assert.deepEqual(weigh()[3], [{ name: 'Emilia Vermaine', words: ['The youngest elder.', 'Emilia Vermaine has black hair.', RAVEN] }], 'only the sentence the check changed is newer — “She” for her name keeps its time');
  assert.equal(archivist.undoLast(b.novelId), true);
  assert.deepEqual(bib.entriesOf(b.novel())[0], before, 'its Undo puts it back as it was, with when each word was written');
  /* an entry kept with no time at all (none of its words' times known) is never the newer: his premise stands over it */
  store.change('novel', b.novelId, (n) => { const x = n.bibliography.find((y) => y.id === 'bb-e'); delete x.at; delete x.saidAt; }, { now: true });
  assert.deepEqual(weigh(), [[LABEL], undefined, undefined, undefined], 'an entry of no known time: the premise stands over it');
  store.change('novel', b.novelId, (n) => { n.bibliography = n.bibliography.map((y) => (y.id === 'bb-e' ? JSON.parse(JSON.stringify(before)) : y)); }, { now: true });
  /* a premise whose time is not known (no written take of it kept): weighed against nothing */
  store.change('chapter', b.ids[0], (ch) => { delete picked(ch.passages[1]).at; }, { now: true });
  assert.equal(shape.premiseAt(b.ch().passages[1]), 0);
  assert.deepEqual(weigh(), [undefined, undefined, undefined, undefined], 'never “older than everything”');
  await putAway(b);
  /* (2.12.41, the review of 2.12.41 and of round 4) a sentence keeps its time only with the same telling words in the
   * same order — the articles alone left out, no word cut to its stem: turned round, a word for another, "he" for "she",
   * a verb's time, "is" made "was", "a son" made "sons", a real word a letter away, is a newer word */
  const timed = (was, now, novel = null) => {
    const prev = { id: 'bb-m', name: 'Mara', aka: [], line: '', text: was, at: 1000 };
    const n = novel || { bibliography: [prev], notes: { people: [], places: [], lore: [], threads: [] } };
    n.bibliography = [prev];
    shape.novelSteps.putEntry({ ...prev, text: now, at: 5000 })(n);
    return [...shape.stampsOf(n.bibliography[0]).values()].map((t) => (t === 1000 ? 'old' : 'new'));
  };
  const card = (about) => ({ bibliography: [], notes: { people: [{ id: 'pe-t', name: 'Tom', about }], places: [], lore: [], threads: [] } });
  assert.deepEqual(timed('Mara hates Tom.', 'Tom hates Mara.'), ['new'], 'turned round');
  assert.deepEqual(timed('Mara serves the Order.', 'The Order serves Mara.'), ['new']);
  assert.deepEqual(timed('He loves her.', 'She loves him.'), ['new'], 'another person');
  assert.deepEqual(timed('Mara is bitten.', 'Mara is bitter.'), ['new'], 'a near word of another meaning');
  assert.deepEqual(timed('Mara is bitten.', 'Mara is bitter.', card('His tea is bitter.')), ['new'], 'a letter changed for another is no slip, though the book says “bitter”');
  assert.deepEqual(timed('She is cruel.', 'She is not cruel.'), ['new']);
  for (const [was, now] of [['Mara loves Tom.', 'Mara loved Tom.'], ['Mara lives in Rome.', 'Mara lived in Rome.'], ['Mara rules the north.', 'Mara ruled the north.'], ['Mara is the queen.', 'Mara was the queen.'], ['Mara has a son.', 'Mara had a son.'], ['Mara has a son.', 'Mara has sons.'], ['Mara is taller than Tom.', 'Mara is taller then Tom.'], ['Mara rules the north.', 'He rules the north.'], ['Tom loves Mara.', 'Tom loves him.'], ['Mara keeps a diary.', 'Mara keeps a dairy.'], ['Mara faces a trial.', 'Mara faces a trail.'], ['Mara is scared of the grove.', 'Mara is sacred of the grove.'], ['Mara and Tom are united.', 'Mara and Tom are untied.'], ['Mara was struck by lightning.', 'Mara was struck by lighting.']]) {
    assert.deepEqual(timed(was, now), ['new'], `${was} → ${now}`);
  }
  assert.deepEqual(timed('Mara loves Tom.', 'Mara loved Tom.', card('He would love to sail.')), ['new'], '“love” in the notes changes nothing');
  assert.deepEqual(timed('She is tall. She is strong.', 'She is tall and strong.'), ['old'], 'two joined');
  assert.deepEqual(timed('She is tall. She is strong.', 'She is strong and tall.'), ['new'], 'two joined, turned round');
  assert.deepEqual(timed('She is tall and strong.', 'She is tall. She is strong.'), ['old', 'old'], 'one said again as two');
  assert.deepEqual(timed('Mara rules the north and fears the sea. She never sleeps.', 'Mara rules the north. She fears the sea. She never sleeps.'), ['old', 'old', 'old'], 'one said again as two, her name and “she” alike');
  assert.deepEqual(timed('She is tall and strong.', 'She is strong. She is tall.'), ['new', 'new'], 'said again as two, turned round');
  assert.deepEqual(timed('She is tall and strong.', 'She is tall. She is strong and kind.'), ['new', 'new'], 'said again as two, a word put in');
  /* her name and the words of her gender, as her entry gives it: "she" where it says "she" or "her" — never "he" */
  assert.deepEqual(timed('Mara keeps the lighthouse. She is strong.', 'She keeps the lighthouse. She is strong.'), ['old', 'old'], 'her name for “she”');
  assert.deepEqual(timed('Mara keeps the lighthouse. She is strong.', 'He keeps the lighthouse. She is strong.'), ['new', 'old'], 'her name for “he”');
  assert.deepEqual(timed('Mara keeps the lighthouse.', 'She keeps the lighthouse.'), ['new'], 'no word for her in her entry: none stands for her name');
  /* a place's entry: "it" for its name, where its own words say "it" */
  const keep = { id: 'bb-k', name: 'The Keep', aka: [], kind: 'places', line: '', text: 'The Keep stands on the cliff. It is old.', at: 1000 };
  const kn = { bibliography: [keep], notes: { people: [], places: [], lore: [], threads: [] } };
  shape.novelSteps.putEntry({ ...keep, text: 'It stands on the cliff. It is old.', at: 5000 })(kn);
  assert.deepEqual([...shape.stampsOf(kn.bibliography[0]).values()].map((t) => (t === 1000 ? 'old' : 'new')), ['old', 'old'], '“it” for the Keep');
  /* (round 5b) a title's stop parts no sentence: "Dr. Halloway treats the hunters." is one, and only it is newer */
  assert.deepEqual(timed('Dr. Halloway treats the hunters. She is kind.', 'Dr. Halloway treats the hunters in secret. She is kind.'), ['new', 'old'], '“Dr. Halloway”');
  /* a slip of the pen: what it was no word of the book, what it is a word the book uses */
  assert.deepEqual(timed('She keeps the lighthuose. She is strong.', 'She keeps the lighthouse. She is strong.', card('He rows out to the lighthouse.')), ['old', 'old'], 'a slip mended');
  assert.deepEqual(timed('She keeps the lighthuose.', 'She keeps the lighthouse.'), ['new'], 'a book that never says “lighthouse”: no slip');
  assert.deepEqual(timed('Mara wears a sliver ring.', 'Mara wears a silver ring.', card('His knife has a silver blade.')), ['old'], 'a slip, where his book never says “sliver”');
  assert.deepEqual(timed('Mara wears a sliver ring.', 'Mara wears a silver ring.', card('He found a sliver of glass by his silver knife.')), ['new'], 'a word his book uses elsewhere is no slip');
});

await test('a slip of the pen in his entry is held to the words of the whole book, its pages too: what it was no word of them, what it is a word they use (2.12.41, round 5)', async () => {
  await setHouse();
  const b = await makeBook([['Mara climbed to the lighthouse at dusk. She kept a diary of the ships.']], { manual: true, brief: 'A keeper finds a letter.' });
  markAllSeen(b);
  let n = 0;
  const times = (was, now) => {
    const id = `bb-${++n}`;
    store.change('novel', b.novelId, shape.novelSteps.putEntry(bib.tidyEntry(bib.newEntry({ id, name: 'Mara', kind: 'people', text: was, at: 1000, by: 'you' }))), { now: true });
    const prev = bib.entriesOf(b.novel()).find((e) => e.id === id);
    store.change('novel', b.novelId, shape.novelSteps.putEntry({ ...prev, text: now, at: 5000 }), { now: true });
    const out = [...shape.stampsOf(bib.entriesOf(b.novel()).find((e) => e.id === id)).values()].map((t) => (t === 1000 ? 'old' : 'new'));
    store.change('novel', b.novelId, shape.novelSteps.dropEntry(id), { now: true });
    return out;
  };
  assert.deepEqual(times('She keeps the lighthuose.', 'She keeps the lighthouse.'), ['old'], 'the page says “lighthouse”');
  assert.deepEqual(times('She keeps a diary.', 'She keeps a dairy.'), ['new'], 'the page says “diary”: no slip');
  assert.deepEqual(times('She keeps a dairy.', 'She keeps a diary.'), ['old'], 'the page says “diary”, never “dairy”: a slip mended');
  await putAway(b);
});

await test('a name changed everywhere reaches his premises, his notes for writing a page again, the chapters’ plans and his entries — the check never makes a card for the old name — and its Undo takes them all back', async () => {
  await setHouse();
  const b = await tomBook();
  const p0 = b.ch().passages[1];
  /* (and a premise of his typed in small letters, his name in it with a possessive) */
  const SMALL = 'tom’s ship comes in at dawn, and mara waits.';
  store.change('chapter', b.ids[0], shape.chapterSteps.addPassage(shape.newPassage('ai', 'The ship came in at dawn. Mara waited on the quay.', { how: 'write', ask: { direction: SMALL, length: 'scene' } })), { now: true });
  /* his note for writing it again, kept on a version of its own */
  store.change('chapter', b.ids[0], (ch) => { const p = ch.passages[1]; p.versions.push(shape.newVersion({ how: 'rewrite', text: 'Tom came home thin from the war. Mara held him at the door.', ask: { note: 'Let Tom limp.', premise: TOM_41 }, from: p.versions[0].id })); p.pick = 1; }, { now: true });
  store.change('chapter', b.ids[0], shape.chapterSteps.setPlan('Tom comes home; Mara opens the door.'), { now: true });
  markAllSeen(b);
  const t0 = Date.now() - 60000;
  store.change('novel', b.novelId, shape.novelSteps.putEntry(bib.tidyEntry(bib.newEntry({ id: 'bb-t', name: 'Tom', aka: ['Tommy'], kind: 'people', line: 'Mara’s brother.', text: 'Tom came home from the war. Tom limps.', at: t0, by: 'you' }))), { now: true });
  /* (the notes checked against his entries as they read) */
  store.change('novel', b.novelId, (n) => { n.memory = { ...(n.memory || {}), audit: { at: Date.now(), reads: 0, v: archivist.AUDIT_V, checked: true, entries: archivist.entriesPrint(n) }, auditAsked: false }; }, { now: true });
  assert.equal(archivist.auditDue(b.novel()), false);
  const made = changes.makeChange(b.novelId, { rename: { from: 'Tom', to: 'Thomas' } });
  assert.equal(made.status, 'made');
  assert.equal(archivist.auditDue(b.novel()), false, 'no check owed for a name changed in his entries and the cards alike');
  assert.ok(made.said.includes('1 entry in the bibliography') && made.said.includes('the premises of 2 passages') && made.said.includes('1 chapter plan'), made.said);
  const p = b.ch().passages[1];
  assert.deepEqual([shape.premiseOf(p), p.versions.map((v) => v.ask.premise || v.ask.direction), picked(p).ask.note], ['Thomas, Mara’s brother, comes home from the war.', ['Thomas, Mara’s brother, comes home from the war.', 'Thomas, Mara’s brother, comes home from the war.'], 'Let Thomas limp.'], 'his premise on every version, and his note');
  assert.equal(shape.premiseOf(b.ch().passages[2]), 'thomas’s ship comes in at dawn, and mara waits.', 'his premise in small letters, as he typed it');
  assert.equal(archivist.groundsOf(b.novel()).loose.includes(' tom '), false, 'the old name no ground of the book');
  assert.equal(b.ch().plan, 'Thomas comes home; Mara opens the door.');
  const e = bib.entriesOf(b.novel())[0];
  assert.deepEqual([e.name, e.aka, e.line, e.text, e.at], ['Thomas', ['Tommy'], 'Mara’s brother.', 'Thomas came home from the war. Thomas limps.', t0]);
  assert.ok([...shape.stampsOf(e).values()].every((t) => t === t0), 'each sentence as old as it was');
  /* the check, told the premise as the book now names him: a card for Tom is never made */
  await reset();
  archivist.askAudit(b.novelId);
  await script([{ text: JSON.stringify({ clear: false, verdict: 'Checked.', people: [{ name: 'Tom', about: 'Mara’s brother, home from the war.', why: 'his premise says so' }] }) }]);
  await archivist.run(b.novelId);
  const check = (await requests()).map((x) => String(x.body.messages.at(-1).content)).find((m) => m.includes(prompts.AUDIT_ASK)) || '';
  assert.ok(check.includes('Thomas, Mara’s brother, comes home from the war.') && !check.includes('Tom, Mara’s brother'), check.slice(check.indexOf('My premises'), check.indexOf('My premises') + 400));
  assert.equal(b.novel().notes.people.some((c) => c.name === 'Tom'), false, 'no card for the old name');
  /* the rename's Undo: his words as he had them */
  assert.equal(changes.undoChange(b.novelId, made).ok, true);
  const q = b.ch().passages[1];
  assert.deepEqual([shape.premiseOf(q), picked(q).ask.note, b.ch().plan, bib.entriesOf(b.novel())[0].name, bib.entriesOf(b.novel())[0].text], [TOM_41, 'Let Tom limp.', 'Tom comes home; Mara opens the door.', 'Tom', 'Tom came home from the war. Tom limps.']);
  assert.equal(shape.premiseOf(b.ch().passages[2]), SMALL);
  assert.equal(p0.id, q.id);
  assert.equal(b.novel().memory.audit.entries, archivist.entriesPrint(b.novel()), 'and the check’s print of his entries with them');
  /* (2.12.41, the review of 2.12.41) his entry changed after the name changed owes its check, the name changed back or not */
  const again = changes.makeChange(b.novelId, { rename: { from: 'Tom', to: 'Thomas' } });
  assert.equal(again.status, 'made');
  assert.equal(archivist.auditDue(b.novel()), false);
  const live = bib.entriesOf(b.novel())[0];
  store.change('novel', b.novelId, shape.novelSteps.putEntry({ ...live, text: `${live.text} Thomas is blind now.`, at: Date.now(), by: 'you' }), { now: true });
  assert.equal(archivist.auditDue(b.novel()), true, 'his edit owes a check');
  assert.equal(changes.undoChange(b.novelId, again).ok, true);
  assert.deepEqual([archivist.auditDue(b.novel()), bib.entriesOf(b.novel())[0].text], [true, 'Thomas came home from the war. Thomas limps. Thomas is blind now.'], 'his edit kept, and still owed its check');
  await putAway(b);
  /* the rename's step for his entry, laid again over a newer copy (his edit in another window meanwhile): the names change
   * in his newer words, and nothing else is written over them */
  const swap = (t) => namesjs.renameIn(t, [{ from: 'Tom', to: 'Thomas' }]);
  const newer = { bibliography: [bib.tidyEntry(bib.newEntry({ id: 'bb-n', name: 'Tom', kind: 'people', text: 'Tom came home. Tom is blind now.', at: 1000, by: 'you' }))], notes: { people: [], places: [], lore: [], threads: [] } };
  assert.equal(changes.renameEntryStep('bb-n', swap)(newer), true);
  assert.deepEqual([newer.bibliography[0].name, newer.bibliography[0].text, [...shape.stampsOf(newer.bibliography[0]).values()]], ['Thomas', 'Thomas came home. Thomas is blind now.', [1000, 1000]]);
  assert.equal(changes.renameEntryStep('bb-n', swap)(newer), false, 'laid twice, the second time changes nothing');
});

await test('a name changed everywhere laid again over another window’s newer copy (its save turned away) changes the names in the newer words and writes nothing else over them — his entry, his words for the book, a card, his premise', async () => {
  await setHouse();
  const b = await tomBook();
  store.change('novel', b.novelId, shape.novelSteps.putEntry(bib.tidyEntry(bib.newEntry({ id: 'bb-t', name: 'Tom', kind: 'people', text: 'Tom came home from the war.', at: 1000, by: 'you' }))), { now: true });
  store.change('novel', b.novelId, shape.novelSteps.setField('brief', 'Tom comes home.'), { now: true });
  await store.flush('novel', b.novelId);
  await store.flush('chapter', b.ids[0]);
  /* another window, meanwhile: his entry, his words for the book and a card changed */
  const got = await (await realFetch(`${BASE}/api/store/novel/${b.novelId}`)).json();
  const theirs = JSON.parse(JSON.stringify(got.data));
  theirs.bibliography[0].text = 'Tom came home from the war. Tom is blind now.';
  theirs.brief = 'Tom comes home, and Mara keeps the light.';
  theirs.notes.people.find((c) => c.id === 'pe-t').about = 'Mara’s brother, blind since the war.';
  const sent = await realFetch(`${BASE}/api/store/novel/${b.novelId}`, { method: 'PUT', headers: { 'Content-Type': 'application/json', 'X-Base': String(got.rev) }, body: JSON.stringify({ data: theirs }) });
  assert.equal(sent.status, 200);
  /* and his premise, typed again there */
  const gotC = await (await realFetch(`${BASE}/api/store/chapter/${b.ids[0]}`)).json();
  const theirsC = JSON.parse(JSON.stringify(gotC.data));
  theirsC.passages[1].versions[0].ask.direction = 'Tom, Mara’s brother, comes home from the war, and Tom limps.';
  const sentC = await realFetch(`${BASE}/api/store/chapter/${b.ids[0]}`, { method: 'PUT', headers: { 'Content-Type': 'application/json', 'X-Base': String(gotC.rev) }, body: JSON.stringify({ data: theirsC }) });
  assert.equal(sentC.status, 200);
  /* this window, its copy older: the name changed everywhere — its save turned away, its steps laid again over the newer copy */
  assert.equal(changes.makeChange(b.novelId, { rename: { from: 'Tom', to: 'Thomas' } }).status, 'made');
  await store.flush('novel', b.novelId);
  await store.flush('chapter', b.ids[0]);
  const kept = await onPhone('novel', b.novelId);
  assert.deepEqual([kept.bibliography[0].name, kept.bibliography[0].text, kept.brief, kept.notes.people.find((c) => c.id === 'pe-t')], ['Thomas', 'Thomas came home from the war. Thomas is blind now.', 'Thomas comes home, and Mara keeps the light.', { ...theirs.notes.people.find((c) => c.id === 'pe-t'), name: 'Thomas' }]);
  const keptC = await onPhone('chapter', b.ids[0]);
  assert.deepEqual([shape.premiseOf(keptC.passages[1]), picked(keptC.passages[1]).text], ['Thomas, Mara’s brother, comes home from the war, and Thomas limps.', 'Thomas came home from the war. Mara held him at the door.'], 'his newer premise with the name changed too');
  await putAway(b);
});

