  const part = { bib: true, text: JSON.stringify({ bibliography: [{ source: 'Chapter One, passage 1', facts: [{ name: 'Emilia', kind: 'people', fact: 'Emilia walks the long hall.', evidence: 'Emilia walked the long hall' }] }] }) };
